/**
 * Component: Auto-Flipping 3D Profile Card with Tailwind CSS
 * Author: @irahoza-daniel (https://tailwindflex.com/@irahoza-daniel)
 * Source: https://tailwindflex.com/@irahoza-daniel/auto-flipping-3d-profile-card-with-tailwind-css
 * Attribution: Créé par @irahoza-daniel sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function AutoFlipping3dProfileCardWithTailwindCss() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Auto Profile Flip Card</title>

  <style>
    .perspective {
      perspective: 1000px;
    }
    .preserve-3d {
      transform-style: preserve-3d;
    }
    .backface-hidden {
      backface-visibility: hidden;
    }
    .rotate-y-180 {
      transform: rotateY(180deg);
    }
    .flip-card-inner {
      transition: transform 0.8s;
      transform-style: preserve-3d;
    }
  </style>
</head>
<body class="bg-gray-200 flex items-center justify-center min-h-screen">

  <div class="w-80 h-96 perspective">
    <div id="flipCard" class="relative w-full h-full flip-card-inner">

      <!-- Front (Profile Info) -->
      <div class="absolute w-full h-full backface-hidden bg-white rounded-xl shadow-lg flex flex-col items-center justify-center p-6">
        <img src="https://randomuser.me/api/portraits/men/75.jpg" alt="Profile" class="w-24 h-24 rounded-full mb-4 border-4 border-blue-500" />
        <h2 class="text-xl font-semibold text-gray-800">John Doe</h2>
        <p class="text-gray-500">Full Stack Developer</p>
      </div>

      <!-- Back (Bio or Contact Info) -->
      <div class="absolute w-full h-full rotate-y-180 backface-hidden bg-white rounded-xl shadow-lg flex flex-col items-center justify-center p-6">
        <h3 class="text-lg font-semibold text-gray-800 mb-2">Contact Me</h3>
        <p class="text-gray-600 text-center mb-1">📧 john.doe@example.com</p>
        <p class="text-gray-600 text-center mb-1">📞 +123 456 7890</p>
        <p class="text-gray-600 text-center">🌍 johndoe.dev</p>
      </div>

    </div>
  </div>



</body>
</html>" }} />
  );
}
